import {EXERCISES} from './exercise-picker.mjs?v=7';
import {api} from './account.js?v=2';
import {localDay} from './store.mjs';
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;};
const input=(label,type,value)=>{const box=el('label',label),i=el('input');i.type=type;i.value=value??'';box.append(i);return {box,i};};
export async function trainerPlanner(root,team,member){
 const section=el('section',undefined,'diary training-planner'),title=el('h2','แผนการฝึก · '+member.display_name),message=el('p');message.setAttribute('role','status');section.append(title,el('p','กำหนดเป้าหมายการฝึกให้ลูกเทรน แยกจากบันทึกที่ฝึกจริง','muted'));root.append(section);
 const form=el('form'),date=input('เริ่มวันที่','date',localDay()),period=el('select');period.setAttribute('aria-label','ช่วงแผน');for(const [v,t] of [['day','วันเดียว'],['week','7 วันจากวันเริ่ม'],['month','จนถึงสิ้นเดือน']]){const o=el('option',t);o.value=v;period.append(o);}const dates=el('div',undefined,'form-row');dates.append(date.box,period);form.append(dates);date.i.required=true;
 const weekdays=el('fieldset');weekdays.append(el('legend','วันฝึกซ้ำในช่วงที่เลือก'));const checks=[];for(const [v,t] of [[1,'จ.'],[2,'อ.'],[3,'พ.'],[4,'พฤ.'],[5,'ศ.'],[6,'ส.'],[0,'อา.']]){const l=el('label',t),c=el('input');c.type='checkbox';c.value=v;c.checked=[1,3,5].includes(v);l.prepend(c);weekdays.append(l);checks.push(c);}weekdays.hidden=true;period.onchange=()=>weekdays.hidden=period.value==='day';form.append(weekdays);
 const suggestions=el('datalist');suggestions.id='plan-exercises-'+crypto.randomUUID();for(const {name} of EXERCISES){const o=el('option');o.value=name;suggestions.append(o);}form.append(suggestions);
 const rows=el('div'),entries=[];function add(){const row=el('div',undefined,'plan-exercise'),name=input('ชื่อท่า','text',''),weight=input('น้ำหนัก (กก.)','number',''),sets=input('เซ็ต','number',3),reps=input('ครั้ง / เซ็ต','number',12),remove=el('button','นำท่าออก','quiet');name.i.required=true;name.i.maxLength=150;name.i.setAttribute('list',suggestions.id);name.i.placeholder='ค้นหาท่าหรือพิมพ์ชื่อเอง';weight.i.min=0;weight.i.max=2000;weight.i.step='.01';for(const f of [sets,reps]){f.i.required=true;f.i.min=1;f.i.step=1;}sets.i.max=100;reps.i.max=1000;remove.type='button';const entry={row,name,weight,sets,reps};entries.push(entry);remove.onclick=()=>{entries.splice(entries.indexOf(entry),1);row.remove();};row.append(name.box,weight.box,sets.box,reps.box,remove);rows.append(row);}add();const more=el('button','+ เพิ่มท่า','quiet');more.type='button';more.onclick=()=>{if(entries.length<30)add();};const save=el('button','บันทึกแผน','primary');form.append(rows,more,save,message);section.append(form);const list=el('div');section.append(list);
 const path='/api/teams/'+team.id+'/plans/'+encodeURIComponent(member.id);
 async function load(){const {plans}=await api(path);list.replaceChildren(el('h3','แผนที่กำหนดไว้'));if(!plans.length)list.append(el('p','ยังไม่มีแผน','muted'));for(const p of plans){const card=el('div',undefined,'entry');card.append(el('h3',p.day));for(const r of p.exercises)card.append(el('p',`${r.exercise} · ${r.sets} เซ็ต × ${r.reps} ครั้ง${r.weight==null?'':' · '+r.weight+' กก.'}`));const b=el('button','ลบแผนวันนี้','quiet');b.type='button';b.onclick=async()=>{if(!confirm('ลบแผนวันที่ '+p.day+'?'))return;try{await api(path+'?id='+p.id,{method:'DELETE'});await load();}catch(e){message.textContent=e.message;}};card.append(b);list.append(card);}}
 form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const result=await api(path,{method:'POST',body:JSON.stringify({start:date.i.value,period:period.value,weekdays:checks.filter(c=>c.checked).map(c=>Number(c.value)),exercises:entries.map(x=>({exercise:x.name.i.value,weight:x.weight.i.value===''?null:Number(x.weight.i.value),sets:Number(x.sets.i.value),reps:Number(x.reps.i.value)}))})});message.textContent='บันทึกแผนแล้ว '+result.count+' วัน';await load();}catch(e){message.textContent=e.message;}finally{save.disabled=false;}};
 await load();section.scrollIntoView({behavior:'smooth',block:'start'});
}
export async function showDailyPlans(root,day){root.replaceChildren();try{const {plans}=await api('/api/plans?day='+day);if(root.dataset.day!==day)return;if(!plans.length)return;root.append(el('h2','แผนจากเทรนเนอร์'));for(const p of plans){const card=el('div',undefined,'entry');card.append(el('h3',p.team_name));for(const r of p.exercises)card.append(el('p',`${r.exercise} · ${r.sets} เซ็ต × ${r.reps} ครั้ง${r.weight==null?'':' · '+r.weight+' กก.'}`));root.append(card);}root.append(el('p','เป้าหมายที่เทรนเนอร์กำหนด บันทึกผลที่ทำจริงในฟอร์มด้านข้าง','muted'));}catch(e){if(root.dataset.day===day)root.append(el('p',e.message,'muted'));}}
